import{_ as r}from"./chunks/measured-not-promised.D-7XFMe9.js";import{_ as a,W as n,o as i,c as d,aa as h,Y as c,a as t,E as o}from"./chunks/framework.vV0l90Ad.js";import"./chunks/theme.D160HLBh.js";const k=JSON.parse(`{"title":"Measured, not promised","description":"Benchmarks lie by default — dead-code elimination, unobserved heaps, harness tax. What it took to publish numbers we'd defend, and the bugs our own harnesses hid.","frontmatter":{"title":"Measured, not promised","description":"Benchmarks lie by default — dead-code elimination, unobserved heaps, harness tax. What it took to publish numbers we'd defend, and the bugs our own harnesses hid.","date":"2026-07"},"headers":[],"relativePath":"blog/measured-not-promised.md","filePath":"blog/measured-not-promised.md","lastUpdated":1786399507000}`),m={name:"blog/measured-not-promised.md"};function p(l,e,u,b,g,f){const s=n("DemoPerf");return i(),d("div",null,[e[0]||(e[0]=h('<h1 id="measured-not-promised" tabindex="-1">Measured, not promised <a class="header-anchor" href="#measured-not-promised" aria-label="Permalink to &quot;Measured, not promised&quot;">​</a></h1><p><img src="'+r+'" alt="Measured, not promised"></p><p>Every library&#39;s benchmarks are flattering. Not because authors lie — because <strong>benchmarks lie by default</strong>, and it takes real work to stop them. Building ivue&#39;s numbers, our own harnesses lied to us three times. This post is the confession log, because the failure modes live in your benchmarks too.</p><p><strong>Lie one: the JIT deleted the competition.</strong> Our first creation benchmark wrote instances into one overwritten variable. V8&#39;s escape analysis elided the competitors&#39; allocations entirely — <code>reactive()</code> &quot;created&quot; 100,000 proxies in 0.0 ms — while ivue&#39;s opaque construction kept honestly paying. The fix: every instance retained in an array, touched after timing. Nothing the optimizer can discard.</p><p><strong>Lie two: the unobserved heap.</strong> Our first memory benchmark read instances <em>outside any effect</em> — and <code>reactive()</code> looked impossibly light, because a proxy allocates its dependency storage only when something subscribes. Live objects are <em>observed</em> objects. Re-measured with every instance read inside its own subscribing effect, the proxy&#39;s real bill arrived: dependency maps for every tracked key.</p><p><strong>Lie three: the harness tax.</strong> Timing operations through a per-call closure added a constant cost to every variant — large enough to hide a 3× difference between two method-call styles. Loop inside the timed region, or measure the harness instead of the code.</p><p>What survived the discipline ships on the <a href="/guide/performance">Performance by Design</a> page with its protocol attached — and the sharpest habit we kept: <strong>run the numbers in the reader&#39;s browser</strong>, on the shipped engine, where no one can quietly pick the machine:</p>',7)),c(s),e[1]||(e[1]=t("p",null,[o("If a claim can't survive its own methodology section, it isn't a result — it's marketing with axes. Steal the harness patterns; they're described under "),t("a",{href:"/guide/benchmarks#methodology"},"Methodology"),o(".")],-1))])}const w=a(m,[["render",p]]);export{k as __pageData,w as default};
